{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Transparent rates and service choices for individual therapy and blended support in {{CITY}}, {{STATE}}.">
  <style>
    :root{--bg:#fbfbfb;--muted:#6b6b6b;--accent:#8aa6a3;--ink:#222;--card:#fff;--glass:rgba(255,255,255,0.7)}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased}
    /* patterned sky using inline svg data-uri */
    body::before{content:"";position:fixed;inset:0;z-index:-1;opacity:0.12;background-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" viewBox="0 0 200 200"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="%238aa6a3"/><stop offset="1" stop-color="%23f0f7f6"/></linearGradient></defs><rect width="200" height="200" fill="url(%23g)"/><g opacity="0.08" fill="none" stroke="%23000000" stroke-width="1"><path d="M10 40c20-20 60-20 80 0s60 20 80 0"/><path d="M10 100c20-20 60-20 80 0s60 20 80 0"/></g></svg>');background-size:cover}
    header{display:flex;justify-content:space-between;align-items:center;padding:28px 36px}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-weight:600}
    .wrap{max-width:960px;margin:28px auto;padding:0 20px}
    .hero{background:linear-gradient(180deg,#fff 0%,#f7f9f8 100%);padding:36px;border-radius:12px;box-shadow:0 6px 24px rgba(20,30,30,0.06);display:grid;grid-template-columns:1fr 240px;gap:20px}
    .hero h1{margin:0 0 8px;font-size:22px}
    .hero p{margin:0;color:var(--muted)}
    .cta{display:flex;flex-direction:column;gap:10px}
    .button{background:var(--accent);color:#fff;border:none;padding:12px;border-radius:8px;font-weight:700;cursor:pointer}
    .soft{background:transparent;border:1px solid rgba(0,0,0,0.06);padding:10px;border-radius:8px}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px;margin-top:22px}
    .card{background:var(--card);padding:18px;border-radius:10px;box-shadow:0 6px 18px rgba(20,30,30,0.04);min-height:140px;display:flex;flex-direction:column;justify-content:space-between;opacity:0;transform:translateY(18px)}
    .price{font-size:20px;font-weight:800}
    small{color:var(--muted)}
    footer{margin:40px 0 120px;color:var(--muted);font-size:13px}
    .note{background:linear-gradient(90deg,rgba(138,166,163,0.06),transparent);padding:12px;border-radius:8px;margin-top:14px}
    /* reveal visible */
    .reveal.is-visible{opacity:1;transform:none;transition:opacity 600ms ease,transform 600ms ease}
    /* reduced motion preferences */
    @media (prefers-reduced-motion:reduce){.reveal{transition:none !important;transform:none !important;opacity:1 !important}}
    /* small */
    @media (max-width:640px){.hero{grid-template-columns:1fr;padding:20px}}
    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(5,6,7,0.5);display:none;align-items:center;justify-content:center;padding:20px}
    .modal{background:var(--card);max-width:720px;width:100%;border-radius:12px;padding:18px;box-shadow:0 10px 40px rgba(10,20,20,0.2)}
    .modal .row{display:flex;gap:12px}
    .meter{height:8px;background:rgba(0,0,0,0.06);border-radius:8px;overflow:hidden}
    .meter > i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),#b7d3d0);width:0}
    .close{background:transparent;border:0;font-weight:700;padding:10px;cursor:pointer}
    .faq-toggle{background:transparent;border:0;padding:12px 0;width:100%;text-align:left}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center"><strong>{{BUSINESS_NAME}}</strong><span style="color:var(--muted)">— thoughtful clinical support</span></div>
    <nav aria-label="Primary">
      <a href="index.html">Gather</a>
      <a href="about.html">Who I Am</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Rates</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero reveal" data-reveal>
      <div>
        <h1>Rates & arrangements</h1>
        <p>Practical choices for individual therapy and blended plans that combine sessions with short-touch support between meetings. Fees are intended to be straightforward; adjustments may be discussed when needed.</p>
        <div class="note">
          <small>I offer both single sessions and curated paths for people wanting steadier support. No promises are made about outcomes — therapy is a collaborative, uncertain process.</small>
        </div>
      </div>
      <aside class="cta">
        <button class="button" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button>
        <button class="soft" id="try-now">Try a short practice</button>
        <div style="color:var(--muted);font-size:13px;padding-top:6px">Phone: {{PHONE}} · {{EMAIL}}</div>
      </aside>
    </section>

    <section style="margin-top:24px">
      <div class="grid">
        <article class="card reveal" data-reveal>
          <div>
            <div style="display:flex;justify-content:space-between;align-items:center"><strong>Single session</strong><span class="price">$185</span></div>
            <p style="margin:8px 0;color:var(--muted)">50-minute focused meeting. Good for intake, medication consultation is not provided here.</p>
          </div>
          <div><small>Sliding scale may be available; ask about limited slots.</small></div>
        </article>

        <article class="card reveal" data-reveal>
          <div>
            <div style="display:flex;justify-content:space-between;align-items:center"><strong>Monthly continuity</strong><span class="price">$600 / mo</span></div>
            <p style="margin:8px 0;color:var(--muted)">Four weekly sessions with brief check-ins by message in-between. Blended care to support momentum.</p>
          </div>
          <div><small>Billed monthly. Cancellation policy applies.</small></div>
        </article>

        <article class="card reveal" data-reveal>
          <div>
            <div style="display:flex;justify-content:space-between;align-items:center"><strong>Short course</strong><span class="price">$1,050</span></div>
            <p style="margin:8px 0;color:var(--muted)">Six-session focused plan (recommended cadence: weekly). Good for targeted concerns or skill-building.</p>
          </div>
          <div><small>Includes brief orientation and a structured closing check-in.</small></div>
        </article>

        <article class="card reveal" data-reveal>
          <div>
            <div style="display:flex;justify-content:space-between;align-items:center"><strong>Session bundle</strong><span class="price">$540 / 3</span></div>
            <p style="margin:8px 0;color:var(--muted)">Three sessions paid up front; useful for people who want short-term review and planning.</p>
          </div>
          <div><small>Bundle refunds handled case-by-case; contact to discuss.</small></div>
        </article>
      </div>

      <div style="margin-top:18px;color:var(--muted)">
        <p><strong>Notes on scope</strong></p>
        <p>Therapy here is a confidential clinical service. I do not provide emergency care; if you are in crisis or danger, please call local emergency services or your nearest crisis line. Sessions are not a substitute for medical or psychiatric treatment when those are needed. We will discuss boundaries, confidentiality limits, and record-keeping during our first meeting.</p>
      </div>
    </section>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
        <div>
          <strong>{{BUSINESS_NAME}}</strong><div style="color:var(--muted)">Serving {{CITY}}, {{STATE}}</div>
        </div>
        <div style="color:var(--muted);font-size:13px">Confidentiality and professional boundaries explained at intake. Payments processed directly; insurance reimbursement is client's responsibility.</div>
      </div>
    </footer>
  </main>

  <!-- Try-it-now modal -->
  <div id="modal" class="modal-backdrop" role="dialog" aria-hidden="true">
    <div class="modal" role="document">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <strong id="modal-title">A brief guided practice</strong>
        <button class="close" id="close-modal">✕</button>
      </div>
      <div style="display:grid;grid-template-columns:1fr 220px;gap:12px">
        <div>
          <p id="modal-desc" style="margin-top:0;color:var(--muted)">Choose a short guided option to steady attention: breathing, journaling, or intention setting.</p>
          <div style="display:flex;gap:8px;margin-bottom:8px">
            <button class="soft" data-mode="breath">Breathing</button>
            <button class="soft" data-mode="journal">Journaling</button>
            <button class="soft" data-mode="intent">Intention</button>
          </div>

          <div id="breath-ui" style="display:none">
            <div class="meter" aria-hidden><i id="breath-bar"></i></div>
            <div style="margin-top:10px;color:var(--muted)" id="breath-status">Ready</div>
            <div style="display:flex;gap:8px;margin-top:12px"><button class="button" id="start-breath">Start 1 min</button><button class="soft" id="stop-breath">Stop</button></div>
          </div>

          <div id="journal-ui" style="display:none">
            <textarea id="journal-text" rows="6" style="width:100%;padding:10px;border-radius:8px;border:1px solid #e6e6e6" placeholder="Write for 5 minutes — freeform."></textarea>
            <div style="display:flex;gap:8px;margin-top:8px"><button class="button" id="save-journal">Save</button><button class="soft" id="clear-journal">Clear</button></div>
            <div style="color:var(--muted);font-size:13px;margin-top:6px">Saved locally to your device only.</div>
          </div>

          <div id="intent-ui" style="display:none">
            <input id="intent-input" placeholder="A short intention for today" style="width:100%;padding:10px;border-radius:8px;border:1px solid #e6e6e6" />
            <div style="display:flex;gap:8px;margin-top:8px"><button class="button" id="save-intent">Set intention</button><button class="soft" id="clear-intent">Clear</button></div>
            <div id="intent-confirm" style="color:var(--muted);font-size:13px;margin-top:6px"></div>
          </div>
        </div>
        <aside style="padding-left:6px">
          <svg width="180" height="160" viewBox="0 0 180 160" xmlns="http://www.w3.org/2000/svg" aria-hidden>
            <defs>
              <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#e8f3f2"/><stop offset="1" stop-color="#ffffff"/></linearGradient>
            </defs>
            <rect width="180" height="160" rx="12" fill="url(#g1)"/>
            <circle id="pulse" cx="90" cy="70" r="28" fill="#8aa6a3" opacity="0.9"></circle>
          </svg>
          <p style="color:var(--muted);font-size:13px;margin-top:8px">A short practice may help focus attention before a session. This is a self-guided exercise and not clinical treatment.</p>
        </aside>
      </div>
    </div>
  </div>

  <script>
    // Modal controls
    const modal = document.getElementById('modal');
    const tryBtn = document.getElementById('try-now');
    const closeBtn = document.getElementById('close-modal');
    tryBtn.addEventListener('click', ()=>{modal.style.display='flex';modal.setAttribute('aria-hidden','false')});
    closeBtn.addEventListener('click', ()=>{modal.style.display='none';modal.setAttribute('aria-hidden','true')});
    modal.addEventListener('click',(e)=>{if(e.target===modal){modal.style.display='none';modal.setAttribute('aria-hidden','true')}});

    // mode switch
    document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click',()=>{
      document.getElementById('breath-ui').style.display='none';
      document.getElementById('journal-ui').style.display='none';
      document.getElementById('intent-ui').style.display='none';
      const mode = btn.getAttribute('data-mode');
      if(mode==='breath') document.getElementById('breath-ui').style.display='block';
      if(mode==='journal') document.getElementById('journal-ui').style.display='block';
      if(mode==='intent') document.getElementById('intent-ui').style.display='block';
    }))

    // breathing practice: simple timing and bar animation
    let breathTimer=null; const bar = document.getElementById('breath-bar');
    document.getElementById('start-breath').addEventListener('click', ()=>{
      let t=0; const total=60; document.getElementById('breath-status').textContent='Breathing — follow the pace';
      if(breathTimer) clearInterval(breathTimer);
      bar.style.width='0%';
      breathTimer=setInterval(()=>{
        t++;
        bar.style.width=((t/total)*100)+'%';
        if(t>=total){clearInterval(breathTimer);breathTimer=null;document.getElementById('breath-status').textContent='Complete — when ready, close this.'}
      },1000);
    });
    document.getElementById('stop-breath').addEventListener('click',()=>{if(breathTimer)clearInterval(breathTimer);breathTimer=null;bar.style.width='0%';document.getElementById('breath-status').textContent='Stopped';});

    // journaling saves locally
    const jt = document.getElementById('journal-text');
    document.getElementById('save-journal').addEventListener('click',()=>{localStorage.setItem('mini-journal',jt.value);alert('Saved locally.');});
    document.getElementById('clear-journal').addEventListener('click',()=>{jt.value='';localStorage.removeItem('mini-journal');});
    // intention
    const intentInput = document.getElementById('intent-input');
    const intentConfirm = document.getElementById('intent-confirm');
    document.getElementById('save-intent').addEventListener('click',()=>{localStorage.setItem('mini-intent',intentInput.value);intentConfirm.textContent='Set: '+intentInput.value});
    document.getElementById('clear-intent').addEventListener('click',()=>{intentInput.value='';localStorage.removeItem('mini-intent');intentConfirm.textContent=''});
    // load saved
    jt.value = localStorage.getItem('mini-journal') || '';
    intentInput.value = localStorage.getItem('mini-intent') || '';

    // scroll reveal with prefers-reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){items.forEach(i=>i.classList.add('is-visible'));return}
      const io = new IntersectionObserver((entries,obs)=>{
        entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');obs.unobserve(e.target)}},{rootMargin:'-10%'})
      );
      items.forEach(i=>io.observe(i));
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Questions — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Common questions about therapy, confidentiality, and practical logistics in {{CITY}}, {{STATE}}.">
  <style>
    :root{--bg:#fff;--ink:#1f1f1f;--muted:#6d6d6d;--accent:#c4d9d6}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;margin:0;background:linear-gradient(180deg,#fdfffe, #f6fbfa);color:var(--ink)}
    .wrap{max-width:880px;margin:28px auto;padding:0 20px}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-weight:600}
    h1{font-size:20px;margin:4px 0}
    .lead{color:var(--muted)}
    .faq{margin-top:18px}
    .qa{background:#fff;padding:14px;border-radius:10px;box-shadow:0 6px 20px rgba(10,20,20,0.04);margin-bottom:12px;opacity:0;transform:translateY(12px)}
    .qa.is-visible{opacity:1;transform:none;transition:opacity 520ms ease,transform 520ms ease}
    .q{display:flex;justify-content:space-between;align-items:center}
    .a{margin-top:8px;color:var(--muted);display:none}
    .toggle{background:transparent;border:0;font-weight:700;cursor:pointer}
    .try{margin-top:12px}
    @media (prefers-reduced-motion:reduce){.qa{opacity:1;transform:none !important}}
    .modal-backdrop{position:fixed;inset:0;background:rgba(5,6,7,0.5);display:none;align-items:center;justify-content:center;padding:20px}
    .modal{background:#fff;max-width:640px;width:100%;border-radius:12px;padding:18px}
  </style>
</head>
<body>
  <header>
    <div><strong>{{BUSINESS_NAME}}</strong><div style="color:var(--muted)">Questions on process and practice</div></div>
    <nav>
      <a href="index.html">Gather</a>
      <a href="about.html">Who I Am</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Rates</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="wrap">
    <h1 class="reveal" data-reveal>Frequently asked</h1>
    <p class="lead">Below are answers to practical questions about confidentiality, boundaries, and how sessions usually work. If something important is missing, please reach out.</p>

    <section class="faq">
      <div class="qa reveal" data-reveal>
        <div class="q"><div><strong>How long is a session?</strong></div><button class="toggle">+</button></div>
        <div class="a">Standard meetings are 50 minutes. Occasionally a different length is arranged when appropriate; we will agree on that in advance.</div>
      </div>

      <div class="qa reveal" data-reveal>
        <div class="q"><div><strong>Is therapy confidential?</strong></div><button class="toggle">+</button></div>
        <div class="a">Yes. I maintain client confidentiality within professional and legal limits. Exceptions include imminent risk of harm to self/others, suspected abuse of a minor, or as required by law. We'll review confidentiality details at intake.</div>
      </div>

      <div class="qa reveal" data-reveal>
        <div class="q"><div><strong>Do you accept insurance?</strong></div><button class="toggle">+</button></div>
        <div class="a">I do not bill insurance directly here. I can provide a receipt (a superbill) that some clients use to request reimbursement. Handling insurance can affect confidentiality; we can talk through options.</div>
      </div>

      <div class="qa reveal" data-reveal>
        <div class="q"><div><strong>What if I'm in crisis?</strong></div><button class="toggle">+</button></div>
        <div class="a">If you are in immediate danger or need urgent help, call emergency services or a local crisis line. This practice is not an emergency service. We will discuss crisis resources as part of care planning.</div>
      </div>

      <div class="qa reveal" data-reveal>
        <div class="q"><div><strong>How do cancellations work?</strong></div><button class="toggle">+</button></div>
        <div class="a">I ask for 48 hours notice for cancellations when possible. Late cancellations or no-shows may be billed at a reduced fee depending on circumstances. We aim for clear, compassionate arrangements.</div>
      </div>
    </section>

    <div style="margin-top:18px;display:flex;gap:10px;align-items:center">
      <button class="button" style="background:#8aa6a3;color:#fff;padding:10px;border-radius:8px;border:0" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button>
      <button class="soft" id="open-practice">Try a short practice</button>
      <div style="color:var(--muted);font-size:13px">Email: {{EMAIL}}</div>
    </div>

    <footer style="margin-top:28px;color:var(--muted);font-size:13px">This site offers general information and is not a substitute for direct clinical care. Confidentiality, scope, and limits will be discussed before beginning therapy.</footer>
  </main>

  <!-- Modal (same guided practice) -->
  <div id="modal" class="modal-backdrop" role="dialog" aria-hidden="true">
    <div class="modal">
      <div style="display:flex;justify-content:space-between;align-items:center"><strong>A brief exercise</strong><button class="close">✕</button></div>
      <p style="color:var(--muted)">This is a small, self-guided breathing exercise. It is not therapy and not monitored.</p>
      <div style="display:flex;gap:8px;margin-top:12px">
        <button id="mini-start" class="button" style="background:#8aa6a3">Begin 1 min</button>
        <button id="mini-stop" class="soft">Stop</button>
      </div>
      <div id="mini-meter" style="margin-top:12px;height:8px;background:#eee;border-radius:8px;overflow:hidden"><i style="display:block;height:100%;width:0;background:linear-gradient(90deg,#8aa6a3,#b7d3d0)"></i></div>
    </div>
  </div>

  <script>
    // Toggle answers
    document.querySelectorAll('.qa').forEach(block=>{
      const btn = block.querySelector('.toggle'); const ans = block.querySelector('.a');
      btn.addEventListener('click', ()=>{
        const open = ans.style.display === 'block';
        ans.style.display = open ? 'none' : 'block';
        btn.textContent = open ? '+' : '–';
      });
    });

    // practice modal
    const outer = document.getElementById('modal');
    const opener = document.getElementById('open-practice');
    const closer = outer.querySelector('.close');
    opener.addEventListener('click', ()=>{outer.style.display='flex';outer.setAttribute('aria-hidden','false')});
    closer.addEventListener('click', ()=>{outer.style.display='none';outer.setAttribute('aria-hidden','true')});
    outer.addEventListener('click',(e)=>{if(e.target===outer){outer.style.display='none';outer.setAttribute('aria-hidden','true')}});

    const miniStart = document.getElementById('mini-start');
    const miniStop = document.getElementById('mini-stop');
    const meter = document.querySelector('#mini-meter i');
    let tmo=null; miniStart.addEventListener('click', ()=>{
      let t=0; const total=60; meter.style.width='0%'; if(tmo)clearInterval(tmo);
      tmo=setInterval(()=>{t++;meter.style.width=((t/total)*100)+'%';if(t>=total){clearInterval(tmo);tmo=null}},1000);
    });
    miniStop.addEventListener('click', ()=>{if(tmo)clearInterval(tmo);tmo=null;meter.style.width='0%'});

    // Reveal on scroll (basic intersection observer)
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const nodes = document.querySelectorAll('.reveal');
      if(prefersReduced){nodes.forEach(n=>n.classList.add('is-visible'));return}
      const io = new IntersectionObserver((entries,obs)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');obs.unobserve(e.target)}}),{threshold:0.12});
      nodes.forEach(n=>io.observe(n));
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Schedule a first meeting or a continuity plan. Select a session type and request times.">
  <style>
    :root{--bg:#f9fdfa;--ink:#1c1c1c;--muted:#6b6b6b;--primary:#8aa6a3}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;margin:0;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:22px}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-weight:600}
    .wrap{max-width:880px;margin:18px auto;padding:0 20px}
    h1{margin:6px 0;font-size:20px}
    .steps{display:grid;grid-template-columns:1fr 320px;gap:20px;margin-top:14px}
    .panel{background:#fff;padding:16px;border-radius:10px;box-shadow:0 8px 26px rgba(10,20,20,0.05)}
    .form-row{display:flex;flex-direction:column;margin-bottom:10px}
    label{font-size:13px;margin-bottom:6px}
    input,select,textarea{padding:10px;border-radius:8px;border:1px solid #e6e6e6}
    .note{color:var(--muted);font-size:13px}
    .button{background:var(--primary);color:#fff;padding:10px;border-radius:8px;border:0;font-weight:700;cursor:pointer}
    .alt{background:transparent;border:1px solid rgba(0,0,0,0.06);padding:10px;border-radius:8px}
    .reveal{opacity:0;transform:translateY(14px)}
    .reveal.is-visible{opacity:1;transform:none;transition:opacity 560ms ease,transform 560ms ease}
    @media (prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none !important}}
  </style>
</head>
<body>
  <header>
    <div><strong>{{BUSINESS_NAME}}</strong><div style="color:var(--muted)">Schedule a conversation</div></div>
    <nav>
      <a href="index.html">Gather</a>
      <a href="about.html">Who I Am</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Rates</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="wrap">
    <h1 class="reveal" data-reveal>Request an appointment</h1>
    <p class="note reveal" data-reveal>Choose a session type and suggest a few times. I will reply with availability and next steps. If you need to ask a question before booking, use the contact page.</p>

    <div class="steps">
      <form class="panel reveal" data-reveal id="book-form" onsubmit="return false" aria-label="Booking form">
        <div class="form-row">
          <label for="type">Session type</label>
          <select id="type" required>
            <option value="">Select</option>
            <option value="single">Single 50-min session — $185</option>
            <option value="shortcourse">Short course (6 sessions) — $1,050</option>
            <option value="continuity">Monthly continuity — $600/month</option>
            <option value="bundle">3-session bundle — $540</option>
          </select>
        </div>

        <div class="form-row">
          <label for="name">Your name</label>
          <input id="name" required placeholder="Full name">
        </div>

        <div class="form-row">
          <label for="email">Email</label>
          <input id="email" required placeholder="you@example.com">
        </div>

        <div class="form-row">
          <label for="phone">Phone (optional)</label>
          <input id="phone" placeholder="Optional">
        </div>

        <div class="form-row">
          <label for="times">Preferred times</label>
          <textarea id="times" rows="3" placeholder="A few days and times that suit you"></textarea>
        </div>

        <div style="display:flex;gap:8px;align-items:center;margin-top:8px">
          <button class="button" id="send-request">Send request</button>
          <button class="alt" id="try-now">Try a short practice</button>
        </div>

        <div class="note" style="margin-top:12px">By requesting a session you agree to receive scheduling replies. Payment details and confidentiality limits will be discussed before an initial meeting.</div>
      </form>

      <aside class="panel reveal" data-reveal>
        <h3 style="margin-top:0">What to expect next</h3>
        <ol style="color:var(--muted)">
          <li>I’ll reply within a few business days with availability and intake instructions.</li>
          <li>We’ll confirm a time and agree on logistical details and cancellation policy.</li>
          <li>At the first meeting we’ll review confidentiality and scope boundaries together.</li>
        </ol>
        <div style="margin-top:12px">
          <strong>Clinic note</strong>
          <p class="note">If you are in immediate crisis, call emergency services or your local crisis line. This scheduling form is not monitored for emergencies.</p>
        </div>
      </aside>
    </div>

    <div style="margin-top:20px;color:var(--muted);font-size:13px">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <strong>{{PHONE}}</strong>. Serving {{CITY}}, {{STATE}}.</div>
  </main>

  <script>
    // reveal
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const nodes = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){nodes.forEach(n=>n.classList.add('is-visible'));return}
      const io = new IntersectionObserver((entries,obs)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');obs.unobserve(e.target)}}),{threshold:0.08});
      nodes.forEach(n=>io.observe(n));
    })();

    // booking form simple handler
    document.getElementById('send-request').addEventListener('click',()=>{
      const name = document.getElementById('name').value.trim();
      const email = document.getElementById('email').value.trim();
      const type = document.getElementById('type').value;
      if(!name||!email||!type){alert('Please provide name, email, and session type.');return}
      // simulate sending; in practice this posts to a secure endpoint
      alert('Request sent. I will respond with available times soon.');
      document.getElementById('book-form').reset();
    });

    // small guided practice (reuse minimal version)
    const modal = document.createElement('div'); modal.style.display='none'; modal.style.position='fixed'; modal.style.inset='0'; modal.style.background='rgba(0,0,0,0.5)'; modal.style.alignItems='center'; modal.style.justifyContent='center';
    modal.innerHTML = '<div style="background:#fff;padding:16px;border-radius:10px;max-width:560px;width:100%"><div style="display:flex;justify-content:space-between"><strong>Short practice</strong><button id="mclose" style="background:none;border:0;font-weight:700">✕</button></div><p style="color:#6b6b6b">One minute of guided breathing can steady attention. Click start and follow a calm pace.</p><div style="display:flex;gap:8px"><button id="mstart" class="button" style="margin-top:6px">Start 1 min</button><button id="mstop" class="alt" style="margin-top:6px">Stop</button></div><div style="height:8px;background:#eee;border-radius:8px;overflow:hidden;margin-top:12px"><i id="mb" style="display:block;height:100%;width:0;background:linear-gradient(90deg,#8aa6a3,#b7d3d0)"></i></div></div>';
    document.body.appendChild(modal);
    document.getElementById('try-now').addEventListener('click',()=>{modal.style.display='flex'});
    modal.querySelector('#mclose').addEventListener('click',()=>{modal.style.display='none'});
    const mb = modal.querySelector('#mb'); let tmo=null; modal.querySelector('#mstart').addEventListener('click',()=>{let t=0;const total=60;mb.style.width='0%';if(tmo)clearInterval(tmo);tmo=setInterval(()=>{t++;mb.style.width=((t/total)*100)+'%';if(t>=total){clearInterval(tmo);tmo=null}},1000)});
    modal.querySelector('#mstop').addEventListener('click',()=>{if(tmo)clearInterval(tmo);tmo=null;mb.style.width='0%'});
  </script>
</body>
</html>"} 
